-- Turns a pixel coordinate into a 12-bit color. Purely combinational.
-- Art (font, logo, background gradient) lives in art.vhd, generated by
-- tools/gen_art.py.
--
-- Three scenes: title, game and game over. Changing scenes plays a sand
-- melt: the screen is split into 4 px columns, each falls under gravity
-- after its own random delay, and every pixel gets a little random slip so
-- the picture breaks into grains. The old scene falls away, then the new
-- one pours in from the top. Only the foreground moves; the gradient
-- behind it stays put. Nothing is stored: each pixel just reads the scene
-- from a shifted row.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.pieces.all;
use work.tetris_pkg.all;
use work.art.all;

entity renderer is
    port (
        pixel_row  : in  std_logic_vector(9 downto 0);
        pixel_col  : in  std_logic_vector(9 downto 0);
        board      : in  board_t;
        cur_shape  : in  shape_t;
        cur_rot    : in  rot_t;
        cur_px     : in  px_t;
        cur_py     : in  py_t;
        ghost_py   : in  py_t;
        next_shape : in  shape_t;
        game_over  : in  std_logic;
        lines_bcd  : in  std_logic_vector(15 downto 0);
        level_bcd  : in  std_logic_vector(7 downto 0);
        show_ghost : in  std_logic;
        piece_on   : in  std_logic;
        anim_rows  : in  std_logic_vector(ROWS - 1 downto 0);
        anim_t     : in  integer range 0 to ANIM_LEN - 1;
        over_t     : in  integer range 0 to OVER_LEN;
        frame_cnt  : in  std_logic_vector(9 downto 0);
        scene      : in  scene_t;
        mphase     : in  mphase_t;
        melt_t     : in  integer range 0 to MELT_LEN - 1;
        scene_t    : in  integer range 0 to 127;
        rgb        : out rgb_t
    );
end renderer;

architecture rtl of renderer is
    -- game layout, in screen pixels
    constant BX0 : integer := 240;            -- board cells, 16 px each
    constant BY0 : integer := 96;
    constant BW  : integer := COLS * 16;
    constant BH  : integer := ROWS * 16;
    constant LX0 : integer := 180;            -- small logo, 8 px blocks
    constant LY0 : integer := 28;
    constant SX0 : integer := 56;             -- stats panel
    constant SY0 : integer := 112;
    constant SW  : integer := 144;
    constant SH  : integer := 120;
    constant NX0 : integer := 440;            -- next panel
    constant NY0 : integer := 112;
    constant NW  : integer := 112;
    constant NH  : integer := 112;
    constant HX0 : integer := 56;             -- controls panel
    constant HY0 : integer := 288;
    constant HH  : integer := 104;
    -- title layout
    constant TX0 : integer := 40;             -- big logo, 16 px blocks
    constant TY0 : integer := 104;

    constant C_WELL     : rgb_t := x"102";
    constant C_GRID     : rgb_t := x"325";
    constant C_PANEL    : rgb_t := x"103";
    constant C_EDGE_HI  : rgb_t := x"A9D";
    constant C_EDGE     : rgb_t := x"647";
    constant C_EDGE_LO  : rgb_t := x"324";
    constant C_LABEL    : rgb_t := x"B9E";
    constant C_VALUE    : rgb_t := x"FFF";
    constant C_HINT     : rgb_t := x"878";
    constant C_SHADOW   : rgb_t := x"201";

    -- is (x, y), relative to the top-left of a string drawn at k x on a
    -- 6k px pitch, inside a lit font pixel? k is a power of two.
    function text_on(s : string; x, y : integer; k : integer := 2) return boolean is
        variable g    : std_logic_vector(0 to 34);
        variable cx   : integer;
        variable code : integer;
    begin
        if y < 0 or y >= 7 * k or x < 0 then
            return false;
        end if;
        for i in 0 to integer(s'length) - 1 loop
            cx := x - i * 6 * k;
            if cx >= 0 and cx < 5 * k then
                code := character'pos(s(s'low + i));
                if code >= 32 and code <= 95 then
                    g := FONT(code);
                    return g((y / k) * 5 + cx / k) = '1';
                end if;
            end if;
        end loop;
        return false;
    end text_on;

    -- same, for a packed BCD number
    function digits_on(v : std_logic_vector; x, y : integer; k : integer := 2) return boolean is
        variable g  : std_logic_vector(0 to 34);
        variable cx : integer;
        variable d  : integer range 0 to 15;
    begin
        if y < 0 or y >= 7 * k or x < 0 then
            return false;
        end if;
        for i in 0 to integer(v'length / 4) - 1 loop
            cx := x - i * 6 * k;
            if cx >= 0 and cx < 5 * k then
                d := to_integer(unsigned(v(v'high - i * 4 downto v'high - i * 4 - 3)));
                g := FONT(48 + d);
                return g((y / k) * 5 + cx / k) = '1';
            end if;
        end loop;
        return false;
    end digits_on;

    -- beveled block of size n: highlight top/left, shadow bottom/right
    function block_px(idx, fx, fy, n, edge : integer) return rgb_t is
    begin
        if fx < edge or fy < edge then
            return palette(idx, 1);
        elsif fx >= n - edge or fy >= n - edge then
            return palette(idx, 2);
        else
            return palette(idx, 0);
        end if;
    end block_px;

    -- framed panel: 4 px beveled border around a fill
    function panel_px(x, y, w, h : integer; fill : rgb_t) return rgb_t is
    begin
        if x < 2 or y < 2 then
            return C_EDGE_HI;
        elsif x >= w - 2 or y >= h - 2 then
            return C_EDGE_LO;
        elsif x < 4 or y < 4 or x >= w - 4 or y >= h - 4 then
            return C_EDGE;
        else
            return fill;
        end if;
    end panel_px;

    -- each 4-bit channel shifted right by n
    function dim(c : rgb_t; n : integer) return rgb_t is
        variable r : rgb_t;
    begin
        for k in 0 to 2 loop
            r(k * 4 + 3 downto k * 4) :=
                std_logic_vector(shift_right(unsigned(c(k * 4 + 3 downto k * 4)), n));
        end loop;
        return r;
    end dim;

    -- mask bit with out-of-box treated as empty
    function in_mask(s : shape_t; rt : rot_t; r, c : integer) return boolean is
    begin
        if r < 0 or r > 3 or c < 0 or c > 3 then
            return false;
        end if;
        return mask_bit(s, rt, r, c) = '1';
    end in_mask;

    function inside(x, y, w, h : integer) return boolean is
    begin
        return x >= 0 and y >= 0 and x < w and y < h;
    end inside;

    -- 4x4 Bayer matrix, for dithering
    function bayer(x, y : std_logic_vector(1 downto 0)) return integer is
        type b_t is array (0 to 15) of integer range 0 to 15;
        constant B : b_t := (0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5);
        variable yx : std_logic_vector(3 downto 0);
    begin
        yx := y & x;
        return B(to_integer(unsigned(yx)));
    end bayer;

    -- LOGO(r, c), read with constant indices (GHDL's synthesizer trips on a
    -- 2-D constant read with two run-time indices)
    function logo_at(r, c : integer) return integer is
        variable v : integer range 0 to 7 := 0;
    begin
        for i in 0 to LOGO_H - 1 loop
            for j in 0 to LOGO_W - 1 loop
                if i = r and j = c then
                    v := LOGO(i, j);
                end if;
            end loop;
        end loop;
        return v;
    end logo_at;

    -- three-band warm gradient for big text, by row inside the glyph
    function fire(y, h : integer) return rgb_t is
    begin
        if y < h / 3 then
            return x"FD5";
        elsif y < 2 * h / 3 then
            return x"F72";
        else
            return x"E23";
        end if;
    end fire;
begin
    process (pixel_row, pixel_col, board, cur_shape, cur_rot, cur_px, cur_py,
             ghost_py, next_shape, game_over, lines_bcd, level_bcd, show_ghost,
             piece_on, anim_rows, anim_t, over_t, frame_cnt, scene, mphase,
             melt_t, scene_t)
        variable col, rr  : integer range 0 to 1023;
        variable row      : integer;
        variable sr       : std_logic_vector(9 downto 0);
        variable visible  : boolean;
        variable bx, by   : integer;
        variable fx, fy   : integer range 0 to 15;
        variable pr, pc   : integer;
        variable cell     : cell_t;
        variable idx      : integer range 0 to 8;
        variable c        : rgb_t;
        variable gi       : integer range 0 to 63;
        variable x, y     : integer;
        variable dist, front : integer;
        variable d, u, off, jit : integer;
        variable g        : std_logic_vector(7 downto 0);
        variable fc       : unsigned(9 downto 0);
        variable li, dy   : integer;
    begin
        col := to_integer(unsigned(pixel_col));
        rr  := to_integer(unsigned(pixel_row));
        fc  := unsigned(frame_cnt);

        -- background: vertical gradient, ordered-dithered between its 16 steps.
        -- It never moves, so the melting scene falls across it.
        gi := (rr + bayer(pixel_col(1 downto 0), pixel_row(1 downto 0)) * 2) / 32;
        if gi > 15 then
            gi := 15;
        end if;
        c := GRAD(gi);

        -- sand melt: which scene row lands on this pixel?
        g   := pixel_col(9 downto 2);
        d   := to_integer(unsigned(g(2 downto 0) xor g(5 downto 3) xor (g(7 downto 6) & g(0))));
        u   := melt_t - d;
        jit := to_integer(unsigned((pixel_col(3 downto 0) xor (pixel_row(1 downto 0) & pixel_row(3 downto 2)))
                                   xor (pixel_col(5 downto 4) & pixel_col(7 downto 6))));
        row := rr;
        if mphase = 1 then
            if u > 0 then
                off := u * u;
                row := rr - off - jit;
            end if;
        elsif mphase = 2 then
            if u <= 0 then
                row := 1023;
            elsif u * u < 480 then
                off := 480 - u * u;
                row := rr + off + jit;
            end if;
        end if;
        visible := row >= 0 and row < 480;
        if visible then
            sr := std_logic_vector(to_unsigned(row, 10));
        else
            sr := (others => '0');
        end if;
        fx := to_integer(unsigned(pixel_col(3 downto 0)));
        fy := to_integer(unsigned(sr(3 downto 0)));

        ---------------------------------------------------------------- title
        if visible and scene = SC_TITLE then
            -- big logo, 16 px blocks; each letter drops in a few frames after
            -- the one before it, and a diagonal shine sweeps across
            x := col - TX0;
            if x >= 0 and x < LOGO_W * 16 then
                li := x / 64;
                dy := li * 3 + 6 - scene_t;
                if dy < 0 then
                    dy := 0;
                end if;
                y := row - TY0 + dy * 24;
                if y >= 0 and y < LOGO_H * 16 then
                    idx := logo_at(y / 16, x / 16);
                    if idx /= 0 then
                        c := block_px(idx, x mod 16, y mod 16, 16, 2);
                        if (x + y - to_integer(fc(6 downto 0)) * 10 + 80) mod 1024 < 14 then
                            c := palette(idx, 1) or x"888";
                        end if;
                    end if;
                elsif y >= LOGO_H * 16 + 4 and y < LOGO_H * 16 + 10 and dy = 0 then
                    -- soft shadow under each landed letter
                    if logo_at(LOGO_H - 1, x / 16) /= 0 then
                        c := C_SHADOW;
                    end if;
                end if;
            end if;

            if scene_t > 40 then
                if text_on("PRESS SPACE", col - 190, row - 248, 4) then
                    c := palette(to_integer(fc(5 downto 3)) mod 7 + 1, 1);
                elsif text_on("PRESS SPACE", col - 193, row - 251, 4) then
                    c := C_SHADOW;
                end if;
            end if;
            if text_on("ARROWS MOVE   UP SPIN   SPACE DROP", col - 116, row - 340) then
                c := C_HINT;
            elsif text_on("KIERAN KLUKAS + NATHAN CROSBY", col - 146, row - 436) then
                c := C_LABEL;
            end if;
        end if;

        ------------------------------------------------------------ game over
        if visible and scene = SC_OVER then
            x := col - 108;
            y := row - 96;
            if text_on("GAME OVER", x, y, 8) then
                c := fire(y, 56);
                if (x - y - to_integer(fc(6 downto 0)) * 10 + 200) mod 1024 < 16 then
                    c := x"FFE";
                end if;
            elsif text_on("GAME OVER", x - 5, y - 5, 8) then
                c := C_SHADOW;
            end if;
            if text_on("LINES", col - 202, row - 210, 4) or text_on("LEVEL", col - 202, row - 254, 4) then
                c := C_LABEL;
            elsif digits_on(lines_bcd, col - 346, row - 210, 4) or digits_on(level_bcd, col - 346, row - 254, 4) then
                c := C_VALUE;
            end if;
            if fc(5) = '0' and text_on("PRESS SPACE", col - 255, row - 360) then
                c := C_VALUE;
            end if;
        end if;

        ----------------------------------------------------------------- game
        if visible and scene = SC_GAME then
            -- small logo
            x := col - LX0;
            y := row - LY0;
            if inside(x, y, LOGO_W * 8, LOGO_H * 8) then
                idx := logo_at(y / 8, x / 8);
                if idx /= 0 then
                    c := block_px(idx, x mod 8, y mod 8, 8, 1);
                end if;
            end if;

            -- board frame and well
            x := col - (BX0 - 8);
            y := row - (BY0 - 8);
            if inside(x, y, BW + 16, BH + 16) then
                c := panel_px(x, y, BW + 16, BH + 16, C_WELL);
            end if;

            if col >= BX0 and col < BX0 + BW and row >= BY0 and row < BY0 + BH then
                bx := to_integer(unsigned(pixel_col(9 downto 4))) - BX0 / 16;
                by := to_integer(unsigned(sr(9 downto 4))) - BY0 / 16;
                if fx = 0 and fy = 0 then
                    c := C_GRID;
                else
                    c := C_WELL;
                end if;

                cell := board(by)(bx);
                pc   := bx + 3 - cur_px;
                idx  := 0;

                -- ghost: a dark tint of the piece's color, with a 1 px edge
                -- only on the outside of the shape, so it reads as one shape
                pr := by - ghost_py;
                if show_ghost = '1' and piece_on = '1' and pc >= 0 and pc <= 3 and pr >= 0 and pr <= 3 then
                    if mask_bit(cur_shape, cur_rot, pr, pc) = '1' then
                        c := dim(palette(cur_shape + 1, 0), 2);
                        if (fy = 0  and not in_mask(cur_shape, cur_rot, pr - 1, pc)) or
                           (fy = 15 and not in_mask(cur_shape, cur_rot, pr + 1, pc)) or
                           (fx = 0  and not in_mask(cur_shape, cur_rot, pr, pc - 1)) or
                           (fx = 15 and not in_mask(cur_shape, cur_rot, pr, pc + 1)) then
                            c := dim(palette(cur_shape + 1, 0), 1);
                        end if;
                    end if;
                end if;

                if cell /= EMPTY then
                    idx := to_integer(unsigned(cell));
                end if;

                pr := by - cur_py;
                if piece_on = '1' and pc >= 0 and pc <= 3 and pr >= 0 and pr <= 3 then
                    if mask_bit(cur_shape, cur_rot, pr, pc) = '1' then
                        idx := cur_shape + 1;
                    end if;
                end if;

                -- game over: a gray curtain rises from the floor
                if game_over = '1' and by >= ROWS - over_t / 2 then
                    idx := GRAY;
                end if;

                if idx /= 0 then
                    c := block_px(idx, fx, fy, 16, 2);

                    -- line clear: flash white, then dissolve outward from the
                    -- middle in a dithered pattern behind a hot leading edge
                    if anim_rows(by) = '1' then
                        if anim_t < 3 then
                            c := block_px(GRAY, fx, fy, 16, 2) or x"CCC";
                        else
                            dist := col - (BX0 + BW / 2);
                            if dist < 0 then
                                dist := -1 - dist;
                            end if;
                            dist  := dist + bayer(pixel_col(1 downto 0), sr(1 downto 0)) * 2;
                            front := (anim_t - 3) * 9;
                            if dist < front - 8 then
                                c := C_WELL;
                            elsif dist < front then
                                c := x"FFC";
                            elsif dist < front + 6 then
                                c := x"FA4";
                            end if;
                        end if;
                    end if;
                end if;
            end if;

            -- stats panel: lines and level
            x := col - SX0;
            y := row - SY0;
            if inside(x, y, SW, SH) then
                c := panel_px(x, y, SW, SH, C_PANEL);
                if text_on("LINES", x - 16, y - 16) or text_on("LEVEL", x - 16, y - 68) then
                    c := C_LABEL;
                elsif digits_on(lines_bcd, x - 16, y - 38) or digits_on(level_bcd, x - 16, y - 90) then
                    c := C_VALUE;
                end if;
            end if;

            -- next piece panel
            x := col - NX0;
            y := row - NY0;
            if inside(x, y, NW, NH) then
                c := panel_px(x, y, NW, NH, C_PANEL);
                if text_on("NEXT", x - 32, y - 14) then
                    c := C_LABEL;
                end if;
                -- spawn-orientation masks sit in different spots of the 4x4 box,
                -- so nudge each to look centered
                x := col - (NX0 + 24);
                y := row - (NY0 + 40);
                if next_shape = 0 then
                    y := y + 8;
                elsif next_shape /= 1 then
                    x := x - 8;
                end if;
                if inside(x, y, 64, 64) then
                    if mask_bit(next_shape, 0, y / 16, x / 16) = '1' then
                        c := block_px(next_shape + 1, x mod 16, y mod 16, 16, 2);
                    end if;
                end if;
            end if;

            -- controls panel
            x := col - HX0;
            y := row - HY0;
            if inside(x, y, SW, HH) then
                c := panel_px(x, y, SW, HH, C_PANEL);
                if text_on("MOVE  A D", x - 16, y - 14) or text_on("SPIN  W Z", x - 16, y - 36)
                   or text_on("SOFT  S", x - 16, y - 58) or text_on("DROP  SPC", x - 16, y - 80) then
                    c := C_HINT;
                end if;
            end if;
        end if;

        rgb <= c;
    end process;
end rtl;
